from lib import background, extend_diagonal_runs

def transform(grid):
    return extend_diagonal_runs(grid)

from collections import Counter, deque

def background(grid):
    """The most frequent color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]


def blocks(g):
    # split by solid uniform nonzero rows and columns
    sr={i for i,row in enumerate(g) if len(set(row))==1 and row[0]!=0}
    sc={j for j in range(len(g[0])) if len({r[j] for r in g})==1 and g[0][j]!=0}
    rs=[i for i in range(len(g)) if i not in sr]; cs=[j for j in range(len(g[0])) if j not in sc]
    # contiguous runs
    def runs(idx):
        out=[]; 
        for i in idx:
            if out and i==out[-1][-1]+1: out[-1].append(i)
            else: out.append([i])
        return out
    rr, cc = runs(rs), runs(cs)
    return [[[[g[i][j] for j in c] for i in r] for c in cc] for r in rr]


def components(grid, color):
    """The 4-connected components of cells of the given color, as lists of (row, col)."""
    from collections import deque
    h, w = len(grid), len(grid[0]); seen = set(); out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == color and (i, j) not in seen:
                q = deque([(i, j)]); seen.add((i, j)); cells = []
                while q:
                    y, x = q.popleft(); cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                            seen.add((ny, nx)); q.append((ny, nx))
                out.append(cells)
    return out


def comps(g,c,conn=8):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    nb=[(dy,dx) for dy in(-1,0,1) for dx in(-1,0,1) if (conn==8 or abs(dy)+abs(dx)==1) and (dy,dx)!=(0,0)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==c and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in nb:
                        a,b=y+dy,x+dx
                        if 0<=a<h and 0<=b<w and g[a][b]==c and (a,b) not in seen:
                            seen.add((a,b)); st.append((a,b))
                out.append(sorted(cells))
    return out

def corner_blocks(grid, fill=None):
    """Split the grid by rows/columns carrying rare marker colors; each lattice block gets color c if all 4 corner markers are c, else the fill color."""
    cnt = Counter(v for row in grid for v in row)
    if fill is None:
        fill = cnt.most_common(1)[0][0]
    keep = set(c for c, _ in cnt.most_common()[2:])
    mr = sorted({i for i, row in enumerate(grid) for j, v in enumerate(row) if v in keep})
    mc = sorted({j for row in grid for j, v in enumerate(row) if v in keep})
    out = []
    for a, b in zip(mr, mr[1:]):
        row = []
        for x, y in zip(mc, mc[1:]):
            cs = {grid[a][x], grid[a][y], grid[b][x], grid[b][y]}
            row.append(cs.pop() if len(cs) == 1 and cs <= keep else fill)
        out.append(row)
    return out



def count_color(grid, color):
    """How many cells of the grid equal color."""
    return sum(v == color for row in grid for v in row)


def downsample_majority(grid, factor=3, bg=(0, 5)):
    """Each factor x factor block becomes one cell: the single non-background color in it, else 0."""
    H = len(grid) // factor
    out = [[0] * H for _ in range(H)]
    for bi in range(H):
        for bj in range(H):
            vs = {grid[i][j] for i in range(bi*factor, bi*factor+factor)
                  for j in range(bj*factor, bj*factor+factor) if grid[i][j] not in bg}
            if len(vs) == 1:
                out[bi][bj] = vs.pop()
    return out





def enclosed_regions(grid):
    """The connected regions of background cells that do not touch the grid border: lists of (row, col)."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg and (i, j) not in seen:
                comp, stack = {(i, j)}, [(i, j)]
                seen.add((i, j))
                border = False
                while stack:
                    y, x = stack.pop()
                    if y in (0, h-1) or x in (0, w-1):
                        border = True
                    for ny, nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            comp.add((ny, nx))
                            stack.append((ny, nx))
                if not border:
                    out.append(comp)
    return out


def extend_diagonal_runs(grid, bg=None):
    """Every diagonal pair of same-colored, non-background cells extends a ray of that color in both diagonal directions, stopping at the grid edge or any non-background cell."""
    h, w = len(grid), len(grid[0])
    if bg is None:
        bg = background(grid)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg: continue
            v = grid[r][c]
            for dr, dc in ((-1,-1),(-1,1),(1,-1),(1,1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == v:
                    a, b = rr + dr, cc + dc
                    while 0 <= a < h and 0 <= b < w and out[a][b] == bg:
                        out[a][b] = v; a += dr; b += dc
                    a, b = r - dr, c - dc
                    while 0 <= a < h and 0 <= b < w and out[a][b] == bg:
                        out[a][b] = v; a -= dr; b -= dc
    return out

def fill_between_walls(grid, wall, fill=3):
    """Non-wall cells with a wall both above and below in their column, or both left and right in their row, become `fill`."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] == wall: continue
            colw = [r for r in range(h) if grid[r][j] == wall]
            roww = [c for c in range(w) if grid[i][c] == wall]
            if (any(r < i for r in colw) and any(r > i for r in colw)) or                (any(c < j for c in roww) and any(c > j for c in roww)):
                out[i][j] = fill
    return out



def fill_bounding_boxes(grid, min_size=4):
    """Keep large same-color components as solid rectangles: fill each component of at least min_size cells with its color over its bounding box, and turn every other non-background cell into the background color."""
    from collections import Counter
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [[bg] * w for _ in range(h)]
    fills = []
    for color in Counter(v for row in grid for v in row):
        if color == bg:
            continue
        for cells in components(grid, color):
            if len(cells) >= min_size:
                ys = [c[0] for c in cells]; xs = [c[1] for c in cells]
                fills.append((min(ys), min(xs), max(ys), max(xs), color))
    for y0, x0, y1, x1, color in fills:
        for i in range(y0, y1 + 1):
            for j in range(x0, x1 + 1):
                out[i][j] = color
    return out



def fill_rect_holes(grid, new=4):
    """Fill every enclosed background region that is a solid rectangle with color `new`."""
    out = [row[:] for row in grid]
    for reg in enclosed_regions(grid):
        if is_solid_rect(reg):
            for i, j in reg:
                out[i][j] = new
    return out



def hmirror(grid):
    """Each row reversed: the grid mirrored left to right."""
    return [row[::-1] for row in grid]


def hstack(a, b):
    """Two grids of equal height joined side by side."""
    return [ra + rb for ra, rb in zip(a, b)]


def is_solid_rect(reg):
    rs=[i for i,j in reg]; cs=[j for i,j in reg]
    return (max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)==len(reg)

def l_stroke(grid, bg):
    """Find the L-shaped stroke (two perpendicular runs sharing a corner cell): (its color, its cells as a set)."""
    h, w = len(grid), len(grid[0])
    for c in {v for row in grid for v in row} - {bg}:
        cells = {(i, j) for i in range(h) for j in range(w) if grid[i][j] == c}
        if len(cells) < 3:
            continue
        ys = [y for y, x in cells]; xs = [x for y, x in cells]
        # an L: every cell on the bounding box edge rows/cols through the corner, no interior cells
        for cy, cx in cells:
            vert = {(y, cx) for y, x in cells}
            hor = {(cy, x) for y, x in cells}
            if (vert | hor) == cells and len(vert) >= 2 and len(hor) >= 2:
                return c, cells
    return None, set()


def line_runs(cells):
    """The parallel straight runs of a set of (row, col) cells: (runs, horiz) when they form at least two equal runs of length > 1, else ([], False)."""
    cells = set(cells)
    if not cells:
        return [], False
    best = ([], False, -1)
    for horiz in (True, False):
        lines = {}
        for y, x in cells:
            key = y if horiz else x
            lines.setdefault(key, []).append((y, x))
        runs = [sorted(v) for k, v in sorted(lines.items())]
        if len(runs) >= 2 and len({len(r) for r in runs}) == 1 and len(runs[0]) > 1:
            if len(runs[0]) > best[2]:
                best = (runs, horiz, len(runs[0]))
    return best[0], best[1]


